export interface City {
  name: string;
  description: string;
  image: string;
}

export interface Country {
  name: string;
  shortName?: string;
  code: string;
  flag: string;
  description: string;
  image: string;
  coordinates: { lat: number; lng: number };
  cities: City[];
  /** IATA code of the primary arrival airport. */
  iata: string;
  /** The city that airport serves. */
  gateway: string;
  capital: string;
  /** İstanbul (IST) kalkışlı yaklaşık uçuş süresi. */
  flightTime: string;
  /** Accent used by that destination's boarding pass. */
  accent: string;
  bestSeason: string;
  budget: "Ekonomik" | "Orta" | "Yüksek";
  signature: string;
}

